def initialize_weights(model, config):
    """Architecture-Adaptive Hybrid Init (AAHI) with residual dampening.
    Orthogonal for VGG (gradient-preserving in deep feed-forward nets),
    Kaiming for residual nets, zero-init last BN in all residual blocks,
    and calibrated Xavier classifier initialization.
    """
    arch, nc = config['arch'], config['num_classes']
    is_resnet = arch.startswith('resnet')
    is_mobile = arch.startswith('mobile')
    use_ortho = arch.startswith('vgg')
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            if use_ortho:
                nn.init.orthogonal_(m.weight, gain=nn.init.calculate_gain('relu'))
            else:
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            if m.out_features == nc:
                nn.init.xavier_normal_(m.weight, gain=1.0)
            else:
                nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)
    if is_resnet:
        for m in model.modules():
            if isinstance(m, BasicBlock):
                nn.init.constant_(m.bn2.weight, 0)
    if is_mobile:
        for m in model.modules():
            if isinstance(m, InvertedResidual) and m.use_res:
                bns = [s for s in m.conv.modules() if isinstance(s, nn.BatchNorm2d)]
                if bns:
                    nn.init.constant_(bns[-1].weight, 0)

def initialize_weights(model, config):
    """Architecture-Adaptive Hybrid Init (AAHI) with residual dampening.

    Key ideas:
    1. Orthogonal init for VGG (preserves gradient norms in deep feed-forward).
    2. Kaiming fan_out for residual convolutions.
    3. Zero-init last BN gamma in every residual block (ResNet & MobileNetV2)
       so residual branches start as identity, stabilizing early training.
    4. Fixup-style scaling of last conv in ResNet residual blocks.
    5. Xavier normal for classifier (avoids over-confident early predictions).
    """
    arch, nc, depth = config['arch'], config['num_classes'], config['depth']
    is_resnet = arch.startswith('resnet')
    is_mobile = arch.startswith('mobile')
    use_ortho = arch.startswith('vgg')
    gain = nn.init.calculate_gain('relu')
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            if use_ortho:
                nn.init.orthogonal_(m.weight, gain=gain)
            else:
                nn.init.kaiming_normal_(m.weight, mode='fan_out', nonlinearity='relu')
        elif isinstance(m, nn.BatchNorm2d):
            nn.init.constant_(m.weight, 1)
            nn.init.constant_(m.bias, 0)
        elif isinstance(m, nn.Linear):
            if m.out_features == nc:
                nn.init.xavier_normal_(m.weight, gain=0.5)
            else:
                if use_ortho:
                    nn.init.orthogonal_(m.weight, gain=gain)
                else:
                    nn.init.kaiming_normal_(m.weight, mode='fan_in', nonlinearity='relu')
            if m.bias is not None:
                nn.init.constant_(m.bias, 0)
    if is_resnet:
        n_blocks = sum(1 for m in model.modules() if isinstance(m, BasicBlock))
        fixup_scale = n_blocks ** (-0.5)
        for m in model.modules():
            if isinstance(m, BasicBlock):
                m.conv2.weight.data.mul_(fixup_scale)
                nn.init.constant_(m.bn2.weight, 0)
    if is_mobile:
        for m in model.modules():
            if isinstance(m, InvertedResidual) and m.use_res:
                bns = [s for s in m.conv.modules() if isinstance(s, nn.BatchNorm2d)]
                if bns:
                    nn.init.constant_(bns[-1].weight, 0)
